namespace ResearchTrack.GitHubService.MutationTests.Features;

public sealed class GitHubRepositoryUrlParserTests
{
    [Theory]
    [InlineData("https://github.com/owner/repository/", "https://github.com/owner/repository")]
    [InlineData("https://github.com/owner/repository.git", "https://github.com/owner/repository")]
    [InlineData("github.com/owner/repository", "https://github.com/owner/repository")]
    public void Normalizes_supported_repository_urls(string input, string expected)
    {
        var parsed = GitHubRepositoryUrlParser.Parse(input);

        Assert.Equal("owner", parsed.Owner);
        Assert.Equal("repository", parsed.Repository);
        Assert.Equal(expected, parsed.NormalizedUrl);
    }

    [Theory]
    [InlineData("")]
    [InlineData("not a url")]
    [InlineData("http://github.com/owner/repository")]
    [InlineData("https://gitlab.com/owner/repository")]
    [InlineData("https://bitbucket.org/owner/repository")]
    [InlineData("https://user:password@github.com/owner/repository")]
    [InlineData("https://github.com/owner")]
    [InlineData("https://github.com/owner/repository/issues")]
    [InlineData("https://github.com/owner/repository/pull/1")]
    [InlineData("https://github.com/owner/repository/tree/main")]
    [InlineData("https://github.com/owner/repository/blob/main/readme.md")]
    [InlineData("https://github.com/owner/repository/settings")]
    [InlineData("https://github.com/owner/repository?tab=readme")]
    [InlineData("https://github.com/owner/repository#readme")]
    [InlineData("https://github.com:444/owner/repository")]
    [InlineData("https://github.com/owner%2Frepository")]
    public void Rejects_malformed_or_unsupported_urls(string input)
    {
        var exception = Assert.Throws<ApiValidationException>(
            () => GitHubRepositoryUrlParser.Parse(input));

        Assert.Equal("repositoryUrl", Assert.Single(exception.FieldErrors).Field);
    }
}

using ResearchTrack.GitHubService.Configuration;
using ResearchTrack.GitHubService.Features.Installation;

namespace ResearchTrack.GitHubService.MutationTests.Features.Installation;

public sealed class GitHubAccessRequestTokenServiceTests
{
    private static readonly Guid RequestId = Guid.Parse("11111111-2222-3333-4444-555555555555");

    [Fact]
    public void Request_token_can_be_recreated_and_verified_without_storing_plaintext()
    {
        var service = CreateService();

        var created = service.CreateRequestToken(RequestId);

        Assert.NotEmpty(created.Nonce);
        Assert.NotEmpty(created.Token);
        Assert.Equal(service.Hash(created.Token), created.Hash);
        Assert.Equal(created.Token, service.RecreateRequestToken(RequestId, created.Nonce));
        Assert.True(service.IsWellFormed(created.Token, RequestId, created.Nonce, resultToken: false));
    }

    [Fact]
    public void Result_token_has_a_separate_purpose_and_cannot_be_reused_as_request_token()
    {
        var service = CreateService();

        var result = service.CreateResultToken(RequestId);

        Assert.True(service.IsWellFormed(result.Token, RequestId, result.Nonce, resultToken: true));
        Assert.False(service.IsWellFormed(result.Token, RequestId, result.Nonce, resultToken: false));
    }

    [Fact]
    public void Tampered_token_is_rejected()
    {
        var service = CreateService();
        var created = service.CreateRequestToken(RequestId);
        var tampered = created.Token + "x";

        Assert.False(service.IsWellFormed(tampered, RequestId, created.Nonce, resultToken: false));
    }



    [Fact]
    public void Request_and_result_tokens_have_distinct_prefixes_and_stable_lowercase_hashes()
    {
        var service = CreateService();
        var id = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var request = service.CreateRequestToken(id);
        var result = service.CreateResultToken(id);

        Assert.StartsWith($"ga1.{id:N}.", request.Token);
        Assert.StartsWith($"gr1.{id:N}.", result.Token);
        Assert.Equal(64, request.Hash.Length);
        Assert.Equal(request.Hash, request.Hash.ToLowerInvariant());
        Assert.Equal(service.Hash(request.Token), request.Hash);
        Assert.NotEqual(request.Token, result.Token);
    }

    [Fact]
    public void Verification_rejects_wrong_request_id_nonce_and_token_purpose()
    {
        var service = CreateService();
        var id = Guid.NewGuid();
        var created = service.CreateRequestToken(id);

        Assert.True(service.IsWellFormed(created.Token, id, created.Nonce, resultToken: false));
        Assert.False(service.IsWellFormed(created.Token, Guid.NewGuid(), created.Nonce, resultToken: false));
        Assert.False(service.IsWellFormed(created.Token, id, created.Nonce + "x", resultToken: false));
        Assert.False(service.IsWellFormed(created.Token, id, created.Nonce, resultToken: true));
    }

    [Fact]
    public void Recreated_tokens_are_deterministic_for_same_context_and_change_when_nonce_changes()
    {
        var service = CreateService();
        var id = Guid.NewGuid();
        var created = service.CreateRequestToken(id);

        Assert.Equal(created.Token, service.RecreateRequestToken(id, created.Nonce));
        Assert.NotEqual(created.Token, service.RecreateRequestToken(id, created.Nonce + "x"));
    }

    private static GitHubAccessRequestTokenService CreateService() => new(
        new GitHubAppOptions(
            12345,
            "researchtrack-test",
            "Iv1.test-client",
            "test-client-secret",
            "/tmp/test.pem",
            new Uri("https://api.example.test/api/github/access-source/install/callback"),
            new Uri("https://app.example.test/"),
            TimeSpan.FromMinutes(10),
            TimeSpan.FromHours(24)));
}

using Microsoft.AspNetCore.Http;
using ResearchTrack.BuildingBlocks.Api.Exceptions;
using ResearchTrack.GitHubService.Configuration;
using ResearchTrack.GitHubService.Domain;
using ResearchTrack.GitHubService.Features.Installation;
using ResearchTrack.GitHubService.Infrastructure;

namespace ResearchTrack.GitHubService.MutationTests.Features.Installation;

public sealed class GitHubInstallationStateServiceTests
{
    private static readonly Guid ProjectId = Guid.Parse("11111111-1111-1111-1111-111111111111");
    private static readonly Guid UserId = Guid.Parse("22222222-2222-2222-2222-222222222222");
    private static readonly DateTimeOffset Now = new(2026, 9, 12, 5, 30, 0, TimeSpan.Zero);

    [Fact]
    public async Task Create_generates_cryptographically_sized_state_and_stores_only_hash()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);

        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/supervisor/projects/11111111-1111-1111-1111-111111111111",
            CancellationToken.None);

        Assert.Equal(43, created.Value.Length);
        Assert.Equal(Now.AddMinutes(10).UtcDateTime, created.ExpiresAt);
        Assert.NotNull(store.State);
        Assert.NotEqual(created.Value, store.State.StateHash);
        Assert.Equal(64, store.State.StateHash.Length);
        Assert.Equal(ProjectId, store.State.ProjectId);
        Assert.Equal(UserId, store.State.InitiatingUserId);
    }

    [Fact]
    public async Task Create_generates_distinct_state_values_for_independent_flows()
    {
        var firstStore = new StubStore();
        var secondStore = new StubStore();
        var first = await CreateService(firstStore, Now).CreateAsync(
            ProjectId, UserId, GitHubInstallationFlowTypes.Direct, "/projects/one", CancellationToken.None);
        var second = await CreateService(secondStore, Now).CreateAsync(
            ProjectId, UserId, GitHubInstallationFlowTypes.Direct, "/projects/two", CancellationToken.None);

        Assert.NotEqual(first.Value, second.Value);
        Assert.NotEqual(firstStore.State?.StateHash, secondStore.State?.StateHash);
    }

    [Fact]
    public async Task Valid_state_is_consumed_once_and_returns_server_side_context()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/supervisor/projects/return-here",
            CancellationToken.None);

        var consumed = await service.ConsumeAsync(
            created.Value,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None);

        Assert.Equal(ProjectId, consumed.ProjectId);
        Assert.Equal(UserId, consumed.InitiatingUserId);
        Assert.Equal("/supervisor/projects/return-here", consumed.ReturnPath);
        Assert.Equal(Now.UtcDateTime, consumed.ConsumedAt);
    }

    [Fact]
    public async Task Expired_state_is_rejected()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/projects/return",
            CancellationToken.None);

        var later = CreateService(store, Now.AddMinutes(11));
        var exception = await Assert.ThrowsAsync<ApiException>(() => later.ConsumeAsync(
            created.Value,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None));

        Assert.Equal(StatusCodes.Status400BadRequest, exception.StatusCode);
        Assert.Contains("expired", exception.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Unknown_state_is_rejected()
    {
        var service = CreateService(new StubStore(), Now);

        var exception = await Assert.ThrowsAsync<ApiException>(() => service.ConsumeAsync(
            "unknown-state-value",
            UserId,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None));

        Assert.Equal(StatusCodes.Status400BadRequest, exception.StatusCode);
        Assert.Contains("unknown", exception.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Replayed_state_is_rejected()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/projects/return",
            CancellationToken.None);

        await service.ConsumeAsync(
            created.Value,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None);

        var exception = await Assert.ThrowsAsync<ApiException>(() => service.ConsumeAsync(
            created.Value,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None));

        Assert.Contains("already", exception.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task State_cannot_be_consumed_by_different_user()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/projects/return",
            CancellationToken.None);

        var exception = await Assert.ThrowsAsync<ApiException>(() => service.ConsumeAsync(
            created.Value,
            Guid.NewGuid(),
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None));

        Assert.Contains("context", exception.Message, StringComparison.OrdinalIgnoreCase);
        Assert.Null(store.State?.ConsumedAt);
    }


    [Fact]
    public async Task Bind_installation_is_idempotent_for_same_installation_and_rejects_mismatch()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            "/projects/return",
            CancellationToken.None);

        var first = await service.BindInstallationAsync(
            created.Value,
            991,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None);
        var second = await service.BindInstallationAsync(
            created.Value,
            991,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None);

        Assert.Equal(991, first.PendingInstallationId);
        Assert.Equal(991, second.PendingInstallationId);

        var exception = await Assert.ThrowsAsync<ApiException>(() => service.BindInstallationAsync(
            created.Value,
            992,
            GitHubInstallationFlowTypes.Direct,
            CancellationToken.None));
        Assert.Equal(StatusCodes.Status400BadRequest, exception.StatusCode);
    }

    [Theory]
    [InlineData("https://evil.example/steal")]
    [InlineData("//evil.example/steal")]
    [InlineData("")]
    public async Task Create_rejects_browser_controlled_external_return_urls(string returnPath)
    {
        var service = CreateService(new StubStore(), Now);

        await Assert.ThrowsAsync<ArgumentException>(() => service.CreateAsync(
            ProjectId,
            UserId,
            GitHubInstallationFlowTypes.Direct,
            returnPath,
            CancellationToken.None));
    }



    [Fact]
    public async Task Exact_expiry_boundary_is_rejected()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(ProjectId, UserId, GitHubInstallationFlowTypes.Direct, "/projects/return", CancellationToken.None);
        Assert.NotNull(store.State);
        store.State!.ExpiresAt = Now.UtcDateTime;

        var ex = await Assert.ThrowsAsync<ApiException>(() => service.ValidateAsync(
            created.Value, UserId, GitHubInstallationFlowTypes.Direct, CancellationToken.None));
        Assert.Equal(StatusCodes.Status400BadRequest, ex.StatusCode);
    }

    [Fact]
    public async Task Validation_rejects_wrong_flow_even_for_same_user_and_valid_state()
    {
        var store = new StubStore();
        var service = CreateService(store, Now);
        var created = await service.CreateAsync(ProjectId, UserId, GitHubInstallationFlowTypes.Direct, "/projects/return", CancellationToken.None);

        var ex = await Assert.ThrowsAsync<ApiException>(() => service.ValidateAsync(
            created.Value, UserId, GitHubInstallationFlowTypes.Requested, CancellationToken.None));
        Assert.Equal(StatusCodes.Status400BadRequest, ex.StatusCode);
    }

    [Theory]
    [InlineData(0L)]
    [InlineData(-1L)]
    public async Task Bind_rejects_non_positive_installation_ids(long installationId)
    {
        var service = CreateService(new StubStore(), Now);
        var ex = await Assert.ThrowsAsync<ApiException>(() => service.BindInstallationAsync(
            "state", installationId, GitHubInstallationFlowTypes.Direct, CancellationToken.None));
        Assert.Equal(StatusCodes.Status400BadRequest, ex.StatusCode);
    }

    [Theory]
    [InlineData("/\\evil")]
    [InlineData("relative/path")]
    [InlineData("   ")]
    public async Task Create_rejects_non_local_return_contexts(string returnPath)
    {
        var service = CreateService(new StubStore(), Now);
        await Assert.ThrowsAsync<ArgumentException>(() => service.CreateAsync(
            ProjectId, UserId, GitHubInstallationFlowTypes.Direct, returnPath, CancellationToken.None));
    }

    [Fact]
    public async Task Create_rejects_empty_project_or_user_identifiers()
    {
        var service = CreateService(new StubStore(), Now);
        await Assert.ThrowsAsync<ArgumentException>(() => service.CreateAsync(
            Guid.Empty, UserId, GitHubInstallationFlowTypes.Direct, "/return", CancellationToken.None));
        await Assert.ThrowsAsync<ArgumentException>(() => service.CreateAsync(
            ProjectId, Guid.Empty, GitHubInstallationFlowTypes.Direct, "/return", CancellationToken.None));
    }

    private static GitHubInstallationStateService CreateService(StubStore store, DateTimeOffset now) => new(
        store,
        new GitHubAppOptions(
            12345,
            "researchtrack-test",
            "Iv1.test-client",
            "test-client-secret",
            "/tmp/test.pem",
            new Uri("https://api.example.test/api/github/access-source/install/callback"),
            new Uri("https://app.example.test/"),
            TimeSpan.FromMinutes(10),
            TimeSpan.FromHours(24)),
        new FixedTimeProvider(now));

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }

    private sealed class StubStore : IGitHubInstallationStateStore
    {
        public GitHubInstallationFlowState? State { get; private set; }

        public Task CreateAsync(GitHubInstallationFlowState state, CancellationToken cancellationToken)
        {
            State = state;
            return Task.CompletedTask;
        }

        public Task<GitHubInstallationFlowState?> TryBindInstallationAsync(
            string stateHash,
            long installationId,
            string expectedFlowType,
            DateTime now,
            CancellationToken cancellationToken)
        {
            if (State is null
                || State.StateHash != stateHash
                || State.FlowType != expectedFlowType
                || State.ConsumedAt is not null
                || State.ExpiresAt <= now
                || (State.PendingInstallationId is long existing && existing != installationId))
            {
                return Task.FromResult<GitHubInstallationFlowState?>(null);
            }

            State.PendingInstallationId ??= installationId;
            State.AuthorizationStartedAt ??= now;
            return Task.FromResult<GitHubInstallationFlowState?>(State);
        }

        public Task<ConsumedGitHubInstallationState?> TryConsumeAsync(
            string stateHash,
            Guid expectedUserId,
            string expectedFlowType,
            DateTime now,
            CancellationToken cancellationToken)
        {
            if (State is null
                || State.StateHash != stateHash
                || State.InitiatingUserId != expectedUserId
                || State.FlowType != expectedFlowType
                || State.ConsumedAt is not null
                || State.ExpiresAt <= now)
            {
                return Task.FromResult<ConsumedGitHubInstallationState?>(null);
            }

            State.ConsumedAt = now;
            return Task.FromResult<ConsumedGitHubInstallationState?>(new(
                State.ProjectId,
                State.InitiatingUserId,
                State.FlowType,
                State.ReturnPath,
                State.AccessRequestId,
                State.PendingInstallationId,
                now));
        }

        public Task<GitHubInstallationFlowState?> FindAsync(
            string stateHash,
            CancellationToken cancellationToken) =>
            Task.FromResult(State?.StateHash == stateHash ? State : null);
    }
}

