        var linkId = Guid.NewGuid();
        await using var db = factory.CreateDbContext();
        db.AccessSources.Add(new GitHubAccessSource
        {
            Id = sourceId,
            ProjectId = projectId,
            CreatedByUserId = Guid.NewGuid(),
            InstallationId = 42,
            OwnerLogin = "owner",
            OwnerType = "User",
            AccessType = "APP",
            ConnectionStatus = connectionStatus,
            Active = true,
            ActiveInstallationKey = activeInstallationKey,
            CreatedAt = DateTime.UtcNow,
            UpdatedAt = DateTime.UtcNow
        });
        db.Repositories.Add(new GitHubRepository
        {
            Id = repositoryId,
            SourceId = sourceId,
            GitHubRepositoryId = 1001,
            FullName = "owner/repo",
            Name = "repo",
            OwnerLogin = "owner",
            DefaultBranch = "main",
            Url = "https://github.com/owner/repo",
            Available = true,
            CreatedAt = DateTime.UtcNow,
            UpdatedAt = DateTime.UtcNow
        });
        db.ProjectRepositoryLinks.Add(new ProjectRepositoryLink
        {
            Id = linkId,
            ProjectId = projectId,
            SourceId = sourceId,
            GitHubRepositoryId = repositoryId,
            GitHubRepoId = 1001,
            LinkedByUserId = Guid.NewGuid(),
            AccessType = "APP",
            FullName = "owner/repo",
            Name = "repo",
            OwnerLogin = "owner",
            DefaultBranch = "main",
            Url = "https://github.com/owner/repo",
            Active = true,
            Enabled = true,
            Primary = true,
            LinkedAt = DateTime.UtcNow,
            SyncStatus = GitHubSyncStatuses.Success,
            UpdatedAt = DateTime.UtcNow
        });
        await db.SaveChangesAsync(ct);
        return new SeedIds(sourceId, repositoryId, linkId);
    }

    private sealed record SeedIds(Guid SourceId, Guid RepositoryId, Guid LinkId);

