using System.Security.Cryptography;
using System.Text;
using ResearchTrack.GitHubService.Configuration;
using ResearchTrack.GitHubService.Features.Webhooks;

namespace ResearchTrack.GitHubService.MutationTests.Features.Webhooks;

public sealed class GitHubWebhookSignatureVerifierTests
{
    private const string Secret = "0123456789abcdef0123456789abcdef0123456789abcdef";

    [Fact]
    public void IsValid_AcceptsMatchingSha256Signature()
    {
        var payload = Encoding.UTF8.GetBytes("{\"zen\":\"Keep it logically awesome.\"}");
        using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(Secret));
        var signature = "sha256=" + Convert.ToHexString(hmac.ComputeHash(payload)).ToLowerInvariant();
        var verifier = new GitHubWebhookSignatureVerifier(Options());
        Assert.True(verifier.IsValid(payload, signature));
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("sha1=deadbeef")]
    [InlineData("sha256=deadbeef")]
    public void IsValid_RejectsMalformedSignature(string? signature)
    {
        var verifier = new GitHubWebhookSignatureVerifier(Options());
        Assert.False(verifier.IsValid(Encoding.UTF8.GetBytes("{}"), signature));
    }

    [Fact]
    public void IsValid_RejectsModifiedPayload()
    {
        var original = Encoding.UTF8.GetBytes("{\"value\":1}");
        using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(Secret));
        var signature = "sha256=" + Convert.ToHexString(hmac.ComputeHash(original)).ToLowerInvariant();
        var verifier = new GitHubWebhookSignatureVerifier(Options());
        Assert.False(verifier.IsValid(Encoding.UTF8.GetBytes("{\"value\":2}"), signature));
    }

    private static GitHubWebhookOptions Options() => new(
        Secret,
        GitHubWebhookOptions.DefaultMaxPayloadBytes,
        GitHubWebhookOptions.DefaultMaxAttempts,
        GitHubWebhookOptions.DefaultProcessingLease,
        GitHubWebhookOptions.DefaultPollInterval);
}

using ResearchTrack.GitHubService.Features.Synchronization;

namespace ResearchTrack.GitHubService.MutationTests.Services;

public sealed class GitHubReconciliationPolicyTests
{
    [Theory]
    [InlineData("main", "abc123", "main", "abc123")]
    [InlineData("main", "ABC123", "main", "abc123")]
    public void HasRemoteChange_UnchangedRepository_ReturnsFalse(
        string localBranch,
        string localHead,
        string remoteBranch,
        string remoteHead)
    {
        Assert.False(GitHubReconciliationPolicy.HasRemoteChange(
            localBranch, localHead, remoteBranch, remoteHead));
    }

    [Theory]
    [InlineData("main", "abc123", "develop", "abc123")]
    [InlineData("main", "abc123", "main", "def456")]
    [InlineData("main", "abc123", "develop", "def456")]
    public void HasRemoteChange_ChangedBranchOrHead_ReturnsTrue(
        string localBranch,
        string localHead,
        string remoteBranch,
        string remoteHead)
    {
        Assert.True(GitHubReconciliationPolicy.HasRemoteChange(
            localBranch, localHead, remoteBranch, remoteHead));
    }

    [Fact]
    public void HasRemoteChange_MissingLocalSnapshot_ReturnsTrue()
    {
        Assert.True(GitHubReconciliationPolicy.HasRemoteChange(null, null, "main", "abc123"));
        Assert.True(GitHubReconciliationPolicy.HasRemoteChange("main", null, "main", "abc123"));
        Assert.True(GitHubReconciliationPolicy.HasRemoteChange(null, "abc123", "main", "abc123"));
    }

    [Fact]
    public void HasRemoteChange_DefaultBranchComparison_IsCaseSensitive()
    {
        Assert.True(GitHubReconciliationPolicy.HasRemoteChange(
            "Main", "abc123", "main", "ABC123"));
    }
}

